const ENTRY = parseRows(ENTRY_ROWS);

const tip = (id, label, icon) => ({ id, label, icon });
const monthNumbers = Array.from({ length: 12 }, (_, index) => index + 1);
const HEALTH_SOURCE = 'https://cdn.who.int/media/docs/default-source/travel-and-health/vaccination-requirements-and-who-recommendations-ith-2022-country-list.pdf';
const SAFETY = new Set(['Afghanistan', 'Iran', 'Iraq', 'Israel', 'N. Korea', 'Lebanon', 'Myanmar (Burma)', 'Syria', 'Yemen']);
// OMS, Anexo 1 (rev. 2023): exigência para chegada de área com risco de febre amarela.
// A rota, duração do trânsito e faixa etária podem alterar a aplicação concreta.
const YELLOW_FEVER = new Set(['Australia', 'Bahrain', 'Bangladesh', 'Brunei', 'Cambodia', 'China', 'Fiji', 'India', 'Indonesia', 'Iran', 'Kazakhstan', 'Malaysia', 'Maldives', 'Myanmar (Burma)', 'Nepal', 'N. Korea', 'Oman', 'Pakistan', 'Papua New Guinea', 'Philippines', 'Qatar', 'Samoa', 'Saudi Arabia', 'Singapore', 'Solomon Islands', 'Sri Lanka', 'Thailand', 'United Arab Emirates']);
const SPECIFIC_DOCUMENTS = {
  Australia: 'Visto Visitor 600 aprovado, declaração de biosegurança, bilhete de saída e prova de hospedagem/recursos.',
  Bhutan: 'Autorização e taxa SDF antes da chegada, reserva do roteiro e bilhete de saída.',
  China: 'Bilhete de saída dentro dos 30 dias, hospedagem/convite e prova da finalidade da visita.',
  Fiji: 'Bilhete de saída, hospedagem e meios financeiros para a permissão de visitante.',
  Indonesia: 'Visa on Arrival B1 ou e-VoA, passagem de saída, hospedagem e declaração eletrônica aplicável.',
  Japan: 'Passaporte brasileiro comum com chip, bilhete de saída e comprovantes do roteiro.',
  Maldives: 'Declaração IMUGA, hospedagem registrada, bilhete de saída e fundos para a estadia.',
  Mongolia: 'Passaporte brasileiro, bilhete de saída, reservas e recursos; confirme regras de trânsito nas conexões até Ulaanbaatar.',
  'New Zealand': 'NZeTA aprovada, declaração de viajante, saída, recursos e observância da biosegurança.',
  Singapore: 'SG Arrival Card, passagem de saída, hospedagem, fundos e CIVP se aplicável à rota.',
  Thailand: 'Bilhete de saída, endereço de hospedagem e Thailand Digital Arrival Card, se vigente na viagem.',
  Türkiye: 'Passagem de saída, hospedagem e recursos; confirme regras de trânsito nas conexões.',
  'United Arab Emirates': 'Passagem de saída, hospedagem, recursos e documentos de trânsito quando a conexão sair do aeroporto.',
  Vanuatu: 'Bilhete de saída, fundos, hospedagem e documentação de menor quando aplicável.'
};
const ENTRY_DECLARATIONS = {
  Maldives: 'Preencher a declaração IMUGA no prazo divulgado pela imigração maldiva.',
  Malaysia: 'Conferir e preencher Malaysia Digital Arrival Card (MDAC), salvo exceção aplicável.',
  'New Zealand': 'Preencher New Zealand Traveller Declaration e declarar itens de biosegurança.',
  Philippines: 'Conferir exigência de eTravel para a chegada.',
  Singapore: 'Enviar SG Arrival Card até três dias antes da chegada, incluindo o dia do voo.',
  Thailand: 'Conferir e enviar Thailand Digital Arrival Card antes da chegada quando aplicável.'
};

export const ASIA_OCEANIA_COMPLETE_ENRICHMENT = Object.freeze(Object.fromEntries(
  Object.entries(OVERVIEW).map(([key, o]) => {
    const c = CULTURE[key];
    const e = ENTRY[key];
    if (!c || !e || o.length !== 11 || c.length !== 7 || e.length !== 5) throw new Error(`Camada AS/OC incompleta: ${key}`);
    const [capital, lang, timezoneLabel, voltage, airport, airportCity, airportList, peakList, shoulderList, bestTime, flightNote] = o;
    const [foodList, etiquetteList, money, transport, connectivity, peakPack, otherPack] = c;
    const [kind, status, maxStay, officialSource, visaPolicyBR] = e;
    const peak = peakList.split(',').map(Number);
    const shoulder = shoulderList.split(',').map(Number);
    const other = monthNumbers.filter(month => !peak.includes(month));
    const docs = SPECIFIC_DOCUMENTS[key] || `Passaporte, bilhete de saída, hospedagem e recursos para ${airportCity}; confirme condições adicionais com a imigração.`;
    const passportValidity = 'Planeje pelo menos seis meses de validade no passaporte como margem prudente; confirme a exigência legal do destino e das conexões antes de viajar.';
    const health = YELLOW_FEVER.has(key)
      ? 'Origem ou trânsito em área de risco de febre amarela pode exigir CIVP; confira a regra específica para a rota e aconselhamento médico para o itinerário.'
      : 'Confira aconselhamento de saúde de viagem e eventuais exigências sanitárias conforme origem, trânsito e itinerário.';
    const entryRequirements = { visaPolicyBR, modality: kind, maxStay, passportValidity, documents: docs, health, officialSource, verifiedAt: '2026-09', status };
    return [key, {
      capital, lang, timezoneLabel, voltage, airport, airportCity,
      majorAirports: airportList.split(','),
      bestTime, months: monthNumbers.map(month => peak.includes(month) ? 2 : shoulder.includes(month) ? 1 : 0), flightNote,
      foods: foodList.split(';').map(value => { const [name, desc] = value.split(':'); return { e: '🍽️', name, desc }; }),
      etiquette: etiquetteList.split(';').map((t, index) => ({ e: ['🤝', '💶', '🗣️', 'ℹ️'][index], t })),
      entryRequirements, healthSource: HEALTH_SOURCE,
      visaPolicyBR: { eligibility: kind === 'free' ? 'visa-free' : kind === 'eta' ? 'authorization' : kind === 'unknown' ? 'unknown' : 'visa-required', detail: visaPolicyBR, verifiedOn: '2026-09', source: officialSource },
      visa: kind === 'free' ? 'free' : kind === 'unknown' ? 'cond' : 'req', visaText: visaPolicyBR,
      passport: passportValidity, vaccines: health,
      borderStatus: SAFETY.has(key) || status === 'needs-review' ? 'warn' : 'open',
      borderNote: SAFETY.has(key) ? `Acesso e segurança exigem avaliação oficial atual. ${visaPolicyBR}` : visaPolicyBR,
      ...(ENTRY_DECLARATIONS[key] ? { entryDeclaration: ENTRY_DECLARATIONS[key] } : {}),
      checklist: [{ group: 'Documentos', items: [
        tip('passport', passportValidity, '📘'), tip('visa', visaPolicyBR, '🛂'), tip('entry-docs', docs, '🧾'),
        ...(YELLOW_FEVER.has(key) ? [tip('yf', 'Conferir necessidade de CIVP de febre amarela para origem e escalas do roteiro.', '💉')] : [])
      ] }],
      travelProfile: {
        moneyTips: [tip('money', money, '💰')],
        healthTips: [tip('health', health, '💊')],
        connectivityTips: [tip('connectivity', connectivity, '📱')],
        transportTips: [tip('arrival', flightNote, '✈️'), tip('local', transport, '🚕')],
        packingTips: [tip('adapter', `Levar adaptador para ${voltage}.`, '🔌')],
        seasonalTips: [
          { id: 'season-peak', months: peak, group: 'Bagagem e clima', items: [tip('season-peak', peakPack, '🧳')] },
          { id: 'season-other', months: other, group: 'Bagagem e clima', items: [tip('season-other', otherPack, '🌦️')] }
        ]
      },
      dataLevel: 'curated'
    }];
  })
));
